-- Create AuditLogs Table
CREATE TABLE "AuditLogs" (
    "LogId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "TimestampUtc" timestamp with time zone NOT NULL DEFAULT (now() AT TIME ZONE 'utc'),
    "UserId" uuid NULL,
    "UserNameSnapshot" character varying(150) NULL,
    "ActionType" character varying(50) NOT NULL,
    "EntityType" character varying(50) NOT NULL,
    "EntityId" character varying(50) NOT NULL,
    "Description" text NOT NULL,
    "BeforeDataJson" text NULL,
    "AfterDataJson" text NULL,
    "IpAddress" character varying(50) NULL,
    "UserAgent" character varying(500) NULL,
    "ReferenceNumber" character varying(100) NULL,
    "Source" character varying(50) NULL,
    "SuccessFlag" boolean NOT NULL,
    CONSTRAINT "PK_AuditLogs" PRIMARY KEY ("LogId")
);

-- Create Indexes
CREATE INDEX "IX_AuditLogs_TimestampUtc" ON "AuditLogs" ("TimestampUtc");
CREATE INDEX "IX_AuditLogs_ActionType" ON "AuditLogs" ("ActionType");
CREATE INDEX "IX_AuditLogs_EntityType" ON "AuditLogs" ("EntityType");
